function memoMultiply() {
  const cache = {};

  return function(a, b) {
    const key = `${a}-${b}`;

    if (cache[key]) {
      return cache[key];
    }

    const result = a * b;
    cache[key] = result;
    return result;
  };
}

const multiply = memoMultiply();
console.log(multiply(2, 5));

